	public void delete( DeleteCooperativeCommand command ) {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(command.getId());

		LOGGER.info( "done deleting of Cooperative id:{0} ", command.getId() );

	}

	/**
	 * Method to retrieve the Cooperative via CooperativeFetchOneSummary.
	 * @param 	summary CooperativeFetchOneSummary
	 * @return 	CooperativeFetchOneResponse
	 */
	public Cooperative getCooperative( CooperativeFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CooperativeFetchOneSummary arg cannot be null" );

		Cooperative entity = null;
		UUID id = summary.getId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Cooperative using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Cooperatives
	 *
	 * @return 	List<Cooperative>
	 */
    public List<Cooperative> getAllCooperative() {
		List<Cooperative> list = projector.findAll( new FindAllCooperativeQuery() );
		return list;
	}


	/**
	 * add Producer to Members
	 * @param		command AssignMembersToCooperativeCommand
	 */
	public void addToMembers( AssignMembersToCooperativeCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToMembers(command.getParentId(), command.getChildIds());
	}

